import{_ as t,l as r,o as a,c as l,v as o,p as n,x as i,d as c,i as p,S as d}from"./chunks/framework.InCnrqk-.js";const f=JSON.parse('{"title":"SYN cookies","description":"","frontmatter":{"title":"SYN cookies","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/syn-cookies.md","filePath":"cs/syn-cookies.md","lastUpdated":1789023840000}'),h={name:"cs/syn-cookies.md"};function S(k,e,C,A,_,N){const s=r("Mermaid");return a(),l("div",null,[e[1]||(e[1]=o('<h1 id="syn-cookies" tabindex="-1">SYN cookies <a class="header-anchor" href="#syn-cookies" aria-label="Permalink to &quot;SYN cookies&quot;">​</a></h1><div class="epigraph"><p>不把半开连接存进队列，而把状态编码进 SYN-ACK 的序号；ACK 回来再重建。抗泛洪，但可能丢掉选项。</p><footer>—— 据 Bernstein 的 SYN cookies 笔记；RFC 4987 TCP SYN Flooding 整理</footer></div><p><a href="/cs/tcp-state-machine">上一课</a> 的 SYN-RECEIVED 要占 TCB。<a href="/cs/tcp-handshake">握手</a> 假定队列够。缺口是 <strong>SYN flood</strong>：伪造源填满半开。cookies 用密码学或哈希把 MSS 等塞进 seq。本课不把 keepalive 写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>攻击者发大量 SYN，源不可达，队列满则合法 SYN 被拒——可用性。Cookie：SYN-ACK 的初始序号 = 哈希(密钥, 四元组, 时间, MSS 编码)，不存 TCB。最终 ACK 校验哈希再创建 ESTABLISHED。代价：时间戳/SACK/缩放可能无法从 32 位里恢复，长肥管道受害者。只在队列压力下启用是常见政策。</p><p>不要把 cookie 写成 TLS cookie 或 QUIC retry 的拷贝，对象类似、编码不同。</p><p><span class="marginnote">RFC 4987 描述攻击与对策。Linux 实现细节不背。密钥要轮换。</span></p><h3 id="半开搬进序号" tabindex="-1">半开搬进序号 <a class="header-anchor" href="#半开搬进序号" aria-label="Permalink to &quot;半开搬进序号&quot;">​</a></h3><p>抗泛洪，可能丢掉缩放等选项。任播要同一密钥验证。压力下启用是常见政策，永久开启要接受降级。</p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对照：存 TCB vs 编码进序号。画：SYN → cookie SYN-ACK → ACK 验证 → 建连。与 RPKI 对照：都是用密码学/哈希抗伪造，一层在路由，一层在传输。</p>',11)),(a(),n(d,null,{default:i(()=>[p(s,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYN%5B%22SYN%20%E4%B8%8D%E5%AD%98%E8%A1%A8%22%5D%20--%3E%20CK%5B%22%E5%BA%8F%E5%8F%B7%3Dcookie%22%5D%0A%20%20CK%20--%3E%20ACK%5B%22%E5%9B%9E%20ACK%22%5D%0A%20%20ACK%20--%3E%20VER%5B%22%E9%AA%8C%E8%AF%81%E5%90%8E%E5%BB%BA%20TCB%22%5D%0A"})]),fallback:i(()=>[...e[0]||(e[0]=[c(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=o('<p>方法止于选定对象与对照；机制才说它如何嵌入已有分层与主干课。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>AIMD 尚未开始，cookies 在握手。MSS 钳制仍可发生在 SYN 上。Anycast 与 ECMP：ACK 必须回到能验证同一密钥的实例，否则失败——接住拓扑课。卫星长 RTT 使 cookie 时间窗要宽容。</p><p>合法瞬时高峰也会触发 cookies，表现为偶发无窗口缩放。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 SYNPROXY 的全部。保活与半开是下一课。后课默认：压力下用 cookie 抗泛洪；选项可能丢。</p><p>把 cookies 当默认永久开启要接受功能降级。</p><p>上一课留下的缺口在本课收口；「SYN cookies」进入后课词汇表后只引用。文献用来钉对象与边界，不把本课写成该主题的独立综述。下一课<a href="/cs/keepalive-half-open">保活与半开</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>半开状态搬进 SYN-ACK 序号。</li><li>抗 SYN 泛洪，可能丢 TCP 选项。</li><li>验证要密钥与时间窗，任播要同源。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 4987；Bernstein cookies。</li></ul>',10))])}const u=t(h,[["render",S]]);export{f as __pageData,u as default};
